-- Ghana admission requirements, copied from each school's own website or the official portal (checked 13 Nov 2026).
-- Only schools where an official page was read. Generic nursing notices from 2016 are not used. Needs step181.
update schools set admission_info = $q${"ug": "BTech: WASSCE C6 or better in English, Core Maths, Integrated Science/Social Studies plus three relevant electives; SSSCE D or better. Many programmes allow HND, diploma or technician routes to Level 200 or 300 (2nd Class Lower HND). Mature applicants 25+ sit an entrance exam with proof of age. Varies by programme.", "english": "International applicants assessed by GTEC; no English test stated on pages read.", "how_to_apply": "Strictly online at https://application.atu.edu.gh. Buy an e-voucher (USSD *924*200*36# or Access, Bank of Africa, Fidelity branches), apply online, keep the summary page. 2026/2027 intake shown as closed.", "deadlines": "2026/2027 application shown as closed. Mature applicant closing date to be announced.", "application_fee": "GHS 250 Masters; GHS 230 BTech, HND, mature, non-tertiary, pre-HND and professional; mature also pay GHS 600 for classes and exam; international applicants free (voucher issued after emailing the university).", "documents": "Passport size photo (160x160px, sea-blue background) is the only item the page lists.", "sources": ["https://atu.edu.gh/how-to-apply-to-atu/", "https://atu.edu.gh/entry-requirements-into-4-year-btech-programmes/"]}$q$::jsonb, admission_link = $q$https://atu.edu.gh/how-to-apply-to-atu/$q$, admission_checked = '2026-11-13' where id = '4a04281e-2e67-48ba-b315-239f9e21bf8b' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Direct entry is on WASSCE/SSSCE results, usually no entrance exam. Mature: age 25 or older by 1 September of the application year, must pass the university entrance exam (subject area and general aptitude), proof of age needed. Post-Diploma: HND or equivalent diploma, usually in the same field.", "how_to_apply": "Online at application.usted.edu.gh with an e-voucher bought at listed banks, Ghana Post or AAMUSTED revenue offices. International applicants request forms by email to academic@aamusted.edu.gh.", "deadlines": "Mature applicants 20 August 2026; direct, post-diploma and postgraduate 30 August 2026 (page headline also mentions 2023/2024, year unclear).", "application_fee": "GHS 230 direct and post-diploma; GHS 345 mature; GHS 288 graduate.", "documents": "Valid email and phone, scanned certified diplomas and transcripts in PDF, digital passport photo 450x450 pixels on plain white background.", "sources": ["https://aamusted.edu.gh/apply/"]}$q$::jsonb, admission_link = $q$https://aamusted.edu.gh/apply/$q$, admission_checked = '2026-11-13' where id = '491d03e2-f074-4fd8-a859-4e05adaa0926' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Foreign and other qualifications assessed by NAB for equivalence. Computer Science needs credit in Physics and Elective Maths. Transfers up to Level 300. Applicants short of requirements may be referred to the Pre-University programme. WASSCE grade rules not stated.", "english": "No test score stated; page says SAT and TOEFL alone are not accepted as entry qualifications.", "how_to_apply": "Apply online (JotForm links on anu.edu.gh/apply-to-anu) or by paper form from Registrar's Office. E-voucher from Ghana Post, Access Bank or *885#.", "application_fee": "GHS 350 graduate; GHS 250 undergraduate; GHS 250 diploma.", "documents": "E-voucher code and serial number, results slip, transcript, passport photo.", "sources": ["https://anu.edu.gh/entry-requirements/", "https://anu.edu.gh/apply-to-anu"]}$q$::jsonb, admission_link = $q$https://anu.edu.gh/entry-requirements/$q$, admission_checked = '2026-11-13' where id = '0457454c-2afd-4d43-9d77-4d2417bec56d' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE/SSSCE: six credits (A1 to C6) incl. English, Maths, Social Studies or Integrated Science, plus three relevant electives. Mature: 25+, five passes incl. English and Maths, three years work experience, pass written exam. Top-up: HND, ACCA, ICA or relevant diploma.", "pg": "MSc: related bachelor degree, at least Second Class Lower, and selection interview.", "how_to_apply": "Buy admission e-voucher (USSD *966*3*3096#, Zenith, Consolidated, Access or Republic Bank, post offices, BTU cash office) then apply at http://btuapps.bolgatu.edu.gh/admissions.", "deadlines": "Entry page shows a 29 September 2023 deadline that has passed; current dates not stated.", "application_fee": "GHS 200 MSc; GHS 150 BSc/BTech, degree and HND mature, weekend, evening; GHS 140 HND/diploma direct and pre-HND; international direct entry USD 100.", "sources": ["https://bolgatu.edu.gh/entry-requirements/", "https://bolgatu.edu.gh/how-to-apply/"]}$q$::jsonb, admission_link = $q$https://bolgatu.edu.gh/entry-requirements/$q$, admission_checked = '2026-11-13' where id = '0912cbe0-73de-4f3b-a3c9-2fd24bd09262' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE C6 (SSSCE D) in English, Maths, Integrated Science plus three relevant electives, aggregate 36 or better in best six. Mature: 25+, 5 years relevant work, E8 in six subjects incl. core, pass entrance exam. HND 2nd Class Lower enters Level 200; Third Class or Pass enters Level 100.", "pg": "MSc/MPhil: at least Second Class Lower in a relevant field, official transcript, concept paper, departmental requirements. PhD: MPhil or MSc research degree, transcript, concept paper.", "how_to_apply": "Buy e-voucher (USSD *776*123#, GCB, Republic, Fidelity, ADB, Access) then apply at https://admissions.utas.edu.gh; print the form and post it with certificates to the Deputy Registrar (Academic Affairs), P.O. Box 24, Navrongo.", "deadlines": "No deadline on the notice; refers to a separate Application Deadlines page. Notice is for 2026/2027.", "application_fee": "E-voucher GHS 200 undergraduate and diploma; GHS 250 postgraduate (2026/2027).", "documents": "WASSCE/SSSCE results; official transcripts and certificates and a concept paper for postgraduate; proof of age and work evidence for mature. Foreign certificates must be verified by GTEC.", "sources": ["https://utas.edu.gh/adms26/", "https://utas.edu.gh/how-to-apply/"]}$q$::jsonb, admission_link = $q$https://utas.edu.gh/adms26/$q$, admission_checked = '2026-11-13' where id = '4f17a5f6-093e-4ba9-8bac-2b641b27b6a7' and country = 'Ghana';
update schools set admission_info = $q${"how_to_apply": "Online portal at cctu.online/admissions for MTech, BTech, HND and Diploma (2025/2026 page). Detailed requirements are in a downloadable PDF.", "fees_link": "https://cctu.edu.gh/site/page.php?id=98661", "sources": ["https://cctu.edu.gh/site/page.php?id=77684"]}$q$::jsonb, admission_link = $q$https://cctu.edu.gh/site/page.php?id=77684$q$, admission_checked = '2026-11-13' where id = '146d9ed8-b871-4938-b172-47d5193c75ea' and country = 'Ghana';
update schools set admission_info = $q${"how_to_apply": "Apply online at https://apply.cug.edu.gh or use PDF undergraduate and postgraduate forms posted to The Registrar, Academic Affairs Unit, P.O. Box 363, Sunyani.", "deadlines": "Strict deadlines mentioned but no dates given; see academic calendar.", "application_fee": "Non-refundable fee paid online; amount not stated.", "documents": "Online: scanned transcripts, certificates, passport or ID, personal statement if applicable. Hard copy: certified copies of results, transcripts, ID, references, proof of fee payment. International: valid passport copy.", "sources": ["https://www.cug.edu.gh/admissions/how-to-apply"]}$q$::jsonb, admission_link = $q$https://www.cug.edu.gh/admissions/how-to-apply$q$, admission_checked = '2026-11-13' where id = 'a02ea19f-15d4-4e36-a928-6931b3495ae5' and country = 'Ghana';
update schools set admission_info = $q${"ug": "FAQ states a D7 in English and Maths does not qualify for a degree programme; the university suggests the ATHE Diploma instead. Full criteria not on the page read.", "how_to_apply": "Buy an e-voucher with PIN (online, bank, or USSD *887*18#), then apply through the form for Undergraduate, Postgraduate, Doctoral, Diploma in Law or ATHE Diploma. Admission status can be checked online.", "sources": ["https://central.edu.gh/international-admissions"]}$q$::jsonb, admission_link = $q$https://central.edu.gh/international-admissions$q$, admission_checked = '2026-11-13' where id = '60203f74-0cfb-4bc7-b662-f3bcb005e9dc' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE credit passes (A1 to C6) in English, Maths, Integrated Science/Social Studies plus three electives, aggregate not above 36 (SSSCE not above 24). Nursing needs Chemistry and Biology. Diploma holders FGPA 3.0+ with five O-Level passes. HND 2nd Class Lower enters Level 200. Mature: 25+, pass entrance exam.", "pg": "Varies by programme: usually at least Second Class Lower in a related degree; some need interview, two years work experience, or ministry recommendation.", "how_to_apply": "Buy e-voucher (mobile money *887*9# code CSU, banks, or card for international), complete online form at https://admission.csuc.edu.gh, print, attach documents and submit.", "deadlines": "No deadline stated; intakes in September and January.", "application_fee": "GHS 200 undergraduate; GHS 300 postgraduate (Ghanaian applicants).", "sources": ["https://www.csuc.edu.gh/entry-requirements-4/", "https://www.csuc.edu.gh/how-to-apply/"]}$q$::jsonb, admission_link = $q$https://www.csuc.edu.gh/entry-requirements-4/$q$, admission_checked = '2026-11-13' where id = 'add311a1-5af2-4825-9140-3f325268fd22' and country = 'Ghana';
update schools set admission_info = $q${"ug": "2025/26 advert: 4-year degree needs WASSCE A1-C6 (SSSCE A-D) in 3 core and 3 electives, or GCE or NABPTEX/CTVET passes. HND needs A1-D7 in 3 core and 2-3 electives. 2-year top-up needs HND Second Class Lower; Pass holders are interviewed. Mature: age 25 or above. 2025 WASSCE candidates may apply awaiting results.", "how_to_apply": "Online at https://admissions.dhltu.edu.gh/ (register an account, pick HND, 4-year or 2-year degree, complete form). Or download the paper form, fill it, scan and send by WhatsApp 039 209 7530 or email admissions@dhltu.edu.gh.", "application_fee": "none (advert says DHLTU forms are free)", "sources": ["https://dhltu.edu.gh/wp-content/uploads/2025/09/2.-DHLTU_Advert_2025-2026.pdf", "https://news.dhltu.edu.gh/?p=139"]}$q$::jsonb, admission_link = $q$https://dhltu.edu.gh/wp-content/uploads/2025/09/2.-DHLTU_Advert_2025-2026.pdf$q$, admission_checked = '2026-11-13' where id = 'c0bdf727-8137-491b-a41e-d6cdfb9aefab' and country = 'Ghana';
update schools set admission_info = $q${"pg": "MPhil Nursing: nursing degree Second Class Lower, N&MC registration, 2 years experience, interview. MPH: first degree Second Class Lower in health or related field, 2 years experience, interview. MSc Midwifery with Research: BSc Midwifery or Nursing plus midwifery diploma, 2 years experience, licence, references, interview.", "how_to_apply": "Midwifery forms from the Accounts Officer, School of Graduate Studies and Research. Page also has an Apply Online button without details. Contact +233 59 691 7184.", "application_fee": "GHS 250 (midwifery application form)", "documents": "Letter of intent or concept note and two references (academic and clinical) for MSc Midwifery.", "sources": ["https://gcuc.edu.gh/academics/school-of-graduate-studies-and-research"]}$q$::jsonb, admission_link = $q$https://gcuc.edu.gh/academics/school-of-graduate-studies-and-research$q$, admission_checked = '2026-11-13' where id = 'cdaef5c0-a790-4bd6-90b0-5a4abb0742aa' and country = 'Ghana';
update schools set admission_info = $q${"ug": "2026/27: WASSCE credits (C6 or better) or SSSCE (D or better) in six subjects incl English, Maths, Integrated Science or Social Studies, plus three electives. GCE, GBCE, ACCA/ICA also accepted. Top-up: HND with GTEC evaluation certificate, entry Level 200 or 300. Mature: age 25+, 5 years work experience, credit in English and Core Maths. Awaiting-result applicants may apply.", "pg": "Bachelor's degree with at least Second Class Lower in a relevant area.", "english": "IB holders without English proficiency must take a three-month English class.", "how_to_apply": "Online at apply.gctu.edu.gh. Pay by mobile money or buy a voucher at any CBG Bank or Ghana Post branch, then complete the online form. Contact: admissions@gctu.edu.gh, 0501579732.", "deadlines": "2026/27 undergraduate admissions, September 2026 intake. No closing date stated.", "application_fee": "GHS 250 (undergraduate voucher)", "documents": "Proof of age for mature applicants, English proficiency certificate where applicable, GTEC evaluation certificate for HND holders, original and translated result slips for IB holders.", "sources": ["https://site.gctu.edu.gh/?p=23902", "https://gs.gctu.edu.gh/faqs/masters-faqs/what-are-the-admission-requirement", "https://site.gctu.edu.gh"]}$q$::jsonb, admission_link = $q$https://site.gctu.edu.gh/?p=23902$q$, admission_checked = '2026-11-13' where id = '5a860e23-d784-4ac1-9cc6-0f3f28938b55' and country = 'Ghana';
update schools set admission_info = $q${"how_to_apply": "Buy the form on https://admissions.gfc.edu.gh/ by Paystack (mobile money or card), log in with the SMS voucher, complete the form, upload documents, submit. Decision comes by SMS. Contact registrar@gfc.edu.gh, +233 54 684 7775.", "deadlines": "2026/27 applications open; no closing date stated.", "documents": "Certified copies of certificates, two referee letters, birth certificate (mature applicants), passport photo, Ghana Card or passport.", "sources": ["https://www.gfc.edu.gh/how-to-apply"]}$q$::jsonb, admission_link = $q$https://www.gfc.edu.gh/how-to-apply$q$, admission_checked = '2026-11-13' where id = '30f438ed-9a4e-41ce-8a58-2e792da99880' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Heritage Christian University College site: WASSCE A1-C6 or SSSCE/GBCE A-D in six subjects incl English and Maths plus three electives. GCE A-Level: three passes plus five O-Level credits. HND: Second Class Lower plus 2 years work experience. ABCE holders may enter Level 200. Mature: age 25+, proof of age, entrance exam in English and Maths or WASSCE credits in both.", "how_to_apply": "Complete the online application on the university website (portal name not stated on page read).", "sources": ["https://hcuc.edu.gh/?p=6384", "https://hcuc.edu.gh/admissions-2"]}$q$::jsonb, admission_link = $q$https://hcuc.edu.gh/?p=6384$q$, admission_checked = '2026-11-13' where id = 'b00a8587-8019-41db-902b-00ecc1200891' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Degree: WASSCE credits A1-C6 in six subjects incl English, Maths, Integrated Science or Social Studies, plus three relevant electives. HND entry: passes A1-D7 in the same subjects. Top-up degree: HND Second Class Lower in a related field, enter Level 300. TVET and GBCE routes also listed. Mature: age 25 and above.", "pg": "Minimum Second Class Lower in a related field.", "how_to_apply": "Buy an e-voucher at GCB, Zenith or Ghana Post, or by mobile money on the portal. Apply at https://app.htu.edu.gh/admissions/ with voucher serial and PIN, then post the printed declaration form and documents to The Registrar, HTU, P.O. Box HP 217, Ho.", "deadlines": "No deadline stated on the pages read.", "application_fee": "E-voucher: GHS 240 graduate, GHS 180 undergraduate (degree, top-up, HND), GHS 150 non-tertiary", "documents": "Printed declaration form, photocopies of certificates or result slips, passport picture. Mature: proof of date of birth. Top-up: transcripts and certificate copies.", "fees_link": "https://htu.edu.gh/2026-2027-fees-schedule/", "sources": ["https://htu.edu.gh/entry-requirements/", "https://htu.edu.gh/how-to-apply/", "https://htu.edu.gh/"]}$q$::jsonb, admission_link = $q$https://htu.edu.gh/entry-requirements/$q$, admission_checked = '2026-11-13' where id = '03bac0e2-78e6-4f01-b1f8-e71123e9ecad' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Bachelor level 100: WASSCE credits C6 or better in core subjects plus three electives, aggregate 36 or better (SSSCE D, aggregate 24). Diploma: credits in core English and Maths plus two electives. Mature: age 25, 3 years work, entrance exam in English, Maths, General Paper.", "english": "Foreign applicants must show proof of English proficiency. No test or score stated.", "how_to_apply": "Online application via iApply at http://application.iug.edu.gh/.", "documents": "Mature applicants: birth certificate copy, employment letters, results.", "sources": ["https://iug.edu.gh/entry-requirements/", "https://iug.edu.gh/admission-policy/"]}$q$::jsonb, admission_link = $q$https://iug.edu.gh/entry-requirements/$q$, admission_checked = '2026-11-13' where id = 'ac53464f-bd53-43e0-9bf7-e4783d3198b1' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Common rule for public Colleges of Education, 2026/2027 B.Ed: WASSCE credits A1-C6 in six subjects: English, Core Maths, Integrated Science or Social Studies plus three relevant electives. SSSCE A-D. GCE A-Level, ABCE and TVET routes also listed. Mature entry not stated.", "english": "Foreign qualifications go to GTEC for equivalence. SAT or TOEFL alone are not accepted as entry qualifications.", "how_to_apply": "Pay for a voucher (PIN) to the Colleges of Education Ghana account, apply at admission.coeportal.edu.gh, rank three colleges, print the form and post it by EMS to the Principal of the first-choice college.", "deadlines": "2025/2026 deadline was 31 August 2025. 2026/2027 common deadline not found.", "application_fee": "GHS350 voucher (2025/2026 procedure notice).", "documents": "Printed online form, one passport photo, copies of results slips where available.", "sources": ["https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf", "https://admission.coeportal.edu.gh/ADMISSION_PROCEDURE_2025.pdf"]}$q$::jsonb, admission_link = $q$https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf$q$, admission_checked = '2026-11-13' where id = '799245a1-7be3-44e9-896f-256a3b6c2dc1' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE C6 or better in 6 subjects: English, Maths, Integrated Science plus three electives, aggregate 36 or better (SSSCE 24). HND first or second upper, or diploma GPA 3.0, also listed. Mature: age 25+ with work experience, criteria not given.", "pg": "Bachelor's degree from a recognised institution and programme minimum GPA. GRE or GMAT only if the programme asks. Interview or portfolio for some programmes.", "english": "International applicants: IELTS 6.0 overall or TOEFL iBT 80.", "how_to_apply": "Online portal at kaafuni.edu.gh/admissions/portal. Forms can be bought by dialling *887*9# and entering KAAF.", "deadlines": "Feb intake: 30 Mar. June intake: 30 Jun. Sept intake: 30 Nov. Year not stated.", "application_fee": "GHS 200", "documents": "Certificates, transcripts, WASSCE/SSSCE results, birth certificate, four passport photos, ID, fee receipt, personal statement, medical certificate, recommendation letters.", "fees_link": "https://kaafuni.edu.gh/fees", "sources": ["https://kaafuni.edu.gh/admissions/undergraduate/requirements", "https://kaafuni.edu.gh/admissions/how-to-apply", "https://kaafuni.edu.gh/admissions/graduate/requirements"]}$q$::jsonb, admission_link = $q$https://kaafuni.edu.gh/admissions/undergraduate/requirements$q$, admission_checked = '2026-11-13' where id = 'a489d2f5-8fc1-498c-8f4a-bef7980efc74' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Common rule for public Colleges of Education, 2026/2027 B.Ed: WASSCE credits A1-C6 in six subjects: English, Core Maths, Integrated Science or Social Studies plus three relevant electives. SSSCE A-D. GCE A-Level, ABCE and TVET routes also listed. Mature entry not stated.", "english": "Foreign qualifications go to GTEC for equivalence. SAT or TOEFL alone are not accepted as entry qualifications.", "how_to_apply": "Pay for a voucher (PIN) to the Colleges of Education Ghana account, apply at admission.coeportal.edu.gh, rank three colleges, print the form and post it by EMS to the Principal of the first-choice college.", "deadlines": "Application deadline 30 September 2026 (2026/2027).", "application_fee": "GHS230 voucher per the college page (2025/2026).", "documents": "Printed online form, one passport photo, copies of results slips where available.", "sources": ["https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf", "https://admission.coeportal.edu.gh/ADMISSION_PROCEDURE_2025.pdf", "https://kpce.edu.gh/apply-to-kpce/", "https://kpce.edu.gh/2026/03/09/colleges-of-education-admissions-open-for-2026-2027-apply-to-kibi-presbyterian-college-of-education/"]}$q$::jsonb, admission_link = $q$https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf$q$, admission_checked = '2026-11-13' where id = 'ee41cba7-671a-443e-8135-09c8080446e1' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE credits A1-C6 in six subjects (three core incl. English and Maths, three electives), aggregate 6-36. SSSCE A-D, aggregate 6-24. Mature: age 25, pass entrance exam in English, Maths and aptitude test.", "how_to_apply": "Buy form at campus Accounts Office or download from website, submit with documents to Admissions Office. Online portal also linked.", "deadlines": "2026/2027 admission open. Intakes: Fall, Winter, Summer sessions. No dates stated.", "application_fee": "Amount not stated; payable at Accounts Office.", "documents": "Signed application form, two passport photos, endorsed results or transcripts, academic reference form.", "fees_link": "https://knutsford.edu.gh/tuition-fees/", "sources": ["https://knutsford.edu.gh/undergraduate-requirements/"]}$q$::jsonb, admission_link = $q$https://knutsford.edu.gh/undergraduate-requirements/$q$, admission_checked = '2026-11-13' where id = 'b5535a13-794f-4379-8d18-339b529b0d82' and country = 'Ghana';
update schools set admission_info = $q${"ug": "B.Tech: WASSCE credits A1-C6 in English, Maths, Integrated Science or Social Studies plus three relevant electives, aggregate 36 or better (SSSCE 24). Mature: age 25, five years work experience, test in English, Maths, General Knowledge. HND graduates enter level 300.", "how_to_apply": "Apply online at https://applyonline.ktu.edu.gh. Eligibility checker at https://ktu.edu.gh/prs.", "fees_link": "https://ktu.edu.gh/category/academic-fees", "sources": ["https://ktu.edu.gh/admissions/undergraduate/requirements/", "https://ktu.edu.gh/admissions"]}$q$::jsonb, admission_link = $q$https://ktu.edu.gh/admissions/undergraduate/requirements/$q$, admission_checked = '2026-11-13' where id = 'e55e5a0b-076d-4202-bf73-e8fd02243c8f' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Common rule for public Colleges of Education, 2026/2027 B.Ed: WASSCE credits A1-C6 in six subjects: English, Core Maths, Integrated Science or Social Studies plus three relevant electives. SSSCE A-D. GCE A-Level, ABCE and TVET routes also listed. Mature entry not stated.", "english": "Foreign qualifications go to GTEC for equivalence. SAT or TOEFL alone are not accepted as entry qualifications.", "how_to_apply": "Pay for a voucher (PIN) to the Colleges of Education Ghana account, apply at admission.coeportal.edu.gh, rank three colleges, print the form and post it by EMS to the Principal of the first-choice college.", "deadlines": "2025/2026 deadline was 31 August 2025. 2026/2027 common deadline not found.", "application_fee": "GHS350 voucher (2025/2026 procedure notice).", "documents": "Printed online form, one passport photo, copies of results slips where available.", "sources": ["https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf", "https://admission.coeportal.edu.gh/ADMISSION_PROCEDURE_2025.pdf"]}$q$::jsonb, admission_link = $q$https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf$q$, admission_checked = '2026-11-13' where id = 'd16fd103-fc47-411a-9b33-882b6e627740' and country = 'Ghana';
update schools set admission_info = $q${"how_to_apply": "Buy an e-voucher at the KsTU cash office or OmniBSIC, CBG and Prudential branches, then apply at https://apply.kstu.edu.gh and upload a passport photo with red background. International applicants use iail.kstu.edu.gh.", "deadlines": "Page shows 'In Progress', no dates.", "application_fee": "GHS200 undergraduate, GHS220 postgraduate, GHS200 HND and Diploma.", "documents": "Passport photo with red background, copies of certificates. MTech: two recommendation letters, motivation letter, transcript.", "sources": ["https://kstu.edu.gh/index.php/admissions/how-to-apply"]}$q$::jsonb, admission_link = $q$https://kstu.edu.gh/index.php/admissions/how-to-apply$q$, admission_checked = '2026-11-13' where id = '96b74ccd-5240-4e29-aec5-162573300271' and country = 'Ghana';
update schools set admission_info = $q${"ug": "2023/2024 notice: WASSCE credits (A1-C6) in English, Maths, Integrated Science plus three electives, aggregate 24 or better in relevant area. Mature applicants 25+: entrance exam and/or interview. HND holders need 3 years work experience plus WASSCE minimum.", "english": "Applicants from French-speaking countries need at least a one-year English proficiency certificate. No test stated for others.", "how_to_apply": "Apply online at https://apps.knust.edu.gh/admissions/ with an e-voucher (Ghana Post or *447*160#; foreign applicants generate it on the portal). Post two printed copies of the application with documents.", "deadlines": "2023/2024: general 30 Nov 2023; mature and top-up 29 Sep 2023.", "application_fee": "GHS250 Ghanaian, USD150 foreign (2023/2024).", "documents": "Two copies of online application, results slips or certificates, certified birth certificate, passport photo with light green background.", "sources": ["https://www.knust.edu.gh/node/3826"]}$q$::jsonb, admission_link = $q$https://www.knust.edu.gh/node/3826$q$, admission_checked = '2026-11-13' where id = 'f601b799-2448-4eed-bbfd-c5efdd72c137' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Common rule for public Colleges of Education, 2026/2027 B.Ed: WASSCE credits A1-C6 in six subjects: English, Core Maths, Integrated Science or Social Studies plus three relevant electives. SSSCE A-D. GCE A-Level, ABCE and TVET routes also listed. Mature entry not stated.", "english": "Foreign qualifications go to GTEC for equivalence. SAT or TOEFL alone are not accepted as entry qualifications.", "how_to_apply": "Pay for a voucher (PIN) to the Colleges of Education Ghana account, apply at admission.coeportal.edu.gh, rank three colleges, print the form and post it by EMS to the Principal of the first-choice college.", "deadlines": "2025/2026 deadline was 31 August 2025. 2026/2027 common deadline not found.", "application_fee": "GHS350 voucher (2025/2026 procedure notice).", "documents": "Printed online form, one passport photo, copies of results slips where available.", "sources": ["https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf", "https://admission.coeportal.edu.gh/ADMISSION_PROCEDURE_2025.pdf"]}$q$::jsonb, admission_link = $q$https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf$q$, admission_checked = '2026-11-13' where id = '41204e58-00f5-4b97-9bd0-7e17e781f8b6' and country = 'Ghana';
