update schools set admission_info = $q${"ug": "Listed under Methodist University Ghana (Dansoman, Tema, Wenchi campuses). Degree: SSSCE/WASSCE credits (A-D) in three core and three electives. Diploma IT: credits in English, Maths, 3 core plus two electives. Mature: age 25+, entrance exam.", "pg": "Masters: good first degree. Education: at least Second Class Lower, or Third Class with 2 years work. PhD: MPhil or research masters, proposal, personal statement, three references.", "how_to_apply": "Buy e-voucher online or via *887*9# (alias MUG), then fill forms at workflow.transflowitc.com using serial and PIN. Details at mug.edu.gh/how-to-apply/.", "deadlines": "2025/2026 August edition, programmes start September 2025. No deadline stated.", "application_fee": "GHS150 UG Ghanaian, GHS300 foreign UG, GHS200 PG Ghanaian, GHS300 foreign PG.", "documents": "Passport photo, certificates and transcripts, CV, referee form, passport bio page for foreigners.", "fees_link": "https://mug.edu.gh/how-to-pay-fees/", "sources": ["https://mug.edu.gh/how-to-apply/", "https://mug.edu.gh/2025-2026-admissions/"]}$q$::jsonb, admission_link = $q$https://mug.edu.gh/how-to-apply/$q$, admission_checked = '2026-11-13' where id = 'f663b6c4-009d-474d-bc50-76dd1039f4bd' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Listed under Methodist University Ghana (Dansoman, Tema, Wenchi campuses). Degree: SSSCE/WASSCE credits (A-D) in three core and three electives. Diploma IT: credits in English, Maths, 3 core plus two electives. Mature: age 25+, entrance exam.", "pg": "Masters: good first degree. Education: at least Second Class Lower, or Third Class with 2 years work. PhD: MPhil or research masters, proposal, personal statement, three references.", "how_to_apply": "Buy e-voucher online or via *887*9# (alias MUG), then fill forms at workflow.transflowitc.com using serial and PIN. Details at mug.edu.gh/how-to-apply/.", "deadlines": "2025/2026 August edition, programmes start September 2025. No deadline stated.", "application_fee": "GHS150 UG Ghanaian, GHS300 foreign UG, GHS200 PG Ghanaian, GHS300 foreign PG.", "documents": "Passport photo, certificates and transcripts, CV, referee form, passport bio page for foreigners.", "fees_link": "https://mug.edu.gh/how-to-pay-fees/", "sources": ["https://mug.edu.gh/how-to-apply/", "https://mug.edu.gh/2025-2026-admissions/"]}$q$::jsonb, admission_link = $q$https://mug.edu.gh/how-to-apply/$q$, admission_checked = '2026-11-13' where id = '77992c62-034e-4770-9d54-000876d7b04d' and country = 'Ghana';
