update schools set admission_info = $q${"ug": "2020 intake notice on school site: age 16-35. Diploma (RGN, midwifery for females): WASSCE aggregate 30 or better in six subjects, credits A1-C6 in English, Maths, Integrated Science. Auxiliary (NAC): aggregate 48 or better. SSSCE: 24 and 30.", "pg": "Post-basic midwifery: age up to 50, medically fit, 3 years experience as NAP or NAC. Not a masters entry.", "how_to_apply": "Buy voucher (PIN and serial number) at an ADB or GCB branch, then fill the form online at healthtraining.gov.gh. Qualified applicants are invited to a competitive interview at the chosen school.", "deadlines": "2020 round: portal open 17 Feb to 30 May 2020 (old year, check current notice).", "application_fee": "GHS 100 voucher (2020). Form-filling help at the college GHS 15.", "documents": "Phone number, personal email, residential address, Ghana Post Digital Address.", "sources": ["https://nmtcteshie.edu.gh/sm/nmtc/?p=3438", "https://nmc.gov.gh/web/phocadownloadpap/ENTRY REQUIREMENT2016.pdf"]}$q$::jsonb, admission_link = $q$https://nmtcteshie.edu.gh/sm/nmtc/?p=3438$q$, admission_checked = '2026-11-13' where id = '9417572b-6f2f-402c-8ffd-a64efc713173' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Diploma: WASSCE/SSSCE credits A1-C6 in six subjects incl English, Maths, Integrated Science and three electives; aggregate 36 or better is highly competitive; age 16 to 35. Degree: aggregate 20 (science) or 18 (non-science). Two-year BSc top-up for RGN diploma holders. Medical exam and interview required.", "pg": "Post-basic degree: RGN, RM or RMN diploma, completed one-year rotation or national service, two years work experience, valid NMC PIN, medically fit, age up to 40.", "how_to_apply": "Buy an application voucher, create an account with voucher serial and PIN on the Online Application Portal (nmtckb.edu.gh/admissions/apply.php), fill form, upload documents, submit and print slip. Shortlisted applicants get SMS/email for interview.", "deadlines": "Applications for 2026/2027 were open per a June 2026 news item; no closing date stated. Interviews listed for 28 November (year not shown).", "documents": "Scanned WASSCE results, ID, passport photo; certified true copies where applicable; medical exam results; NMC PIN for post-basic; foreign certificates interpreted by GTEC and WAEC.", "fees_link": "https://nmtckb.edu.gh/fees-2", "sources": ["https://www.nmtckb.edu.gh/admissions/requirements.php", "https://www.nmtckb.edu.gh/admissions/application-guide.php", "https://www.nmtckb.edu.gh/?p=152", "https://nmtckb.edu.gh/fees-2"]}$q$::jsonb, admission_link = $q$https://www.nmtckb.edu.gh/admissions/requirements.php$q$, admission_checked = '2026-11-13' where id = 'a8ef3f29-3c40-4ee8-8df0-3177b3f6bc74' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE/SSSCE/GBCE: six credits, three core (incl English and Maths) plus three electives. Mature entry: age 25 or more, two years relevant work experience, written exam and interview. HND (good, 2nd Class Lower) with two years work experience can enter LLB; ABCE diploma holders may enter Level 200. Page dated 2021.", "english": "Foreign qualifications must be assessed by GTEC; no English test stated.", "how_to_apply": "Apply online at eportal.pentvars.edu.gh. LLB applicants write a qualifying entrance exam, then interview.", "application_fee": "GHC 200 for the LLB qualifying entrance exam (page undated, paid before exams).", "documents": "Certificates for the entry route; birth certificate or proof of age for mature applicants; for nursing top-up: NMC certificate, transcript, WASSCE results, birth certificate, two passport photos.", "sources": ["https://pentvars.edu.gh/?p=11279", "https://pentvars.edu.gh/?p=11243"]}$q$::jsonb, admission_link = $q$https://pentvars.edu.gh/?p=11279$q$, admission_checked = '2026-11-13' where id = '82dd4e90-5fff-43e6-b69e-103d50c23fd4' and country = 'Ghana';
update schools set admission_info = $q${"ug": "General: aggregate 24 or better (SSSCE/GBCE) or 36 or better (WASSCE). Programme rules: Nursing and Midwifery need C6 or better in English, Core Maths and Integrated Science; Maths/ICT and Economics need elective Maths or C4 in Core Maths. Mature applicants: age 25 or more with work experience, pass entrance exam in English, Maths and aptitude. A preliminary programme exists for weak results.", "english": "No English test stated; Nursing needs C6 in English; mature applicants write an English exam.", "how_to_apply": "Complete two paper application forms (duplicate) with photos and proof of payment; deposit at a listed location or send by EMS/FedEx. Contact admission@presbyuniversity.edu.gh.", "application_fee": "Amount not stated on guidelines page (2018 guidelines).", "documents": "Two completed forms, three photos (one endorsed), bank draft/receipt copy, pre-paid return envelopes, evidence of date of birth for mature applicants, WAEC PIN for international applicants.", "sources": ["https://www.presbyuniversity.edu.gh/site/?p=2567", "https://www.presbyuniversity.edu.gh/site/wp-content/uploads/2018/08/Guidelines-for-Completion-of-Application-Forms.pdf"]}$q$::jsonb, admission_link = $q$https://www.presbyuniversity.edu.gh/site/?p=2567$q$, admission_checked = '2026-11-13' where id = '1ca794ce-d2bb-4e1c-b942-1c2bce491f8b' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE credits A1-C6 (SSSCE A-D) in six subjects: three core incl English and Maths plus three electives. HND/Diploma 2nd Class Lower or better may enter Level 200. Mature entry: age 25 or more, pass in English and Maths; exam and interview 15 August 2025. Diploma: three credits in specialisation and passes in English and Maths.", "pg": "MPhil/MSc/MA/MPA/MPH/MBA: good first degree, at least Second Class Lower (Third Class case by case), transcripts, short research proposal for MPhil, interview. PhD: MPhil/MSc or equivalent, proposal, interview.", "english": "No English test stated; credit in English at WASSCE/SSSCE required.", "how_to_apply": "Online at admissions.ubids.edu.gh: pay fee, get e-voucher, fill form, upload photo and certificates, print summary, send documents in triplicate by Ghana Post EMS to Director, Academic Affairs, Wa.", "deadlines": "2024/2025 weekend postgraduate: open 15 March 2024, close 31 May 2024. No current UG deadline stated.", "application_fee": "GH¢205 (2024/2025 postgraduate weekend page).", "documents": "Passport photo, certificates and result slips, official transcripts, research proposal (PhD/MPhil), printed application summary, proof of age for mature applicants.", "sources": ["https://ubids.edu.gh/admissions/admissions-requirements", "https://ubids.edu.gh/announcements/sob-weekend-postgraduate-programmes-admissions"]}$q$::jsonb, admission_link = $q$https://ubids.edu.gh/admissions/admissions-requirements$q$, admission_checked = '2026-11-13' where id = 'b1443b85-72cf-4d22-bd9c-b788aa43133b' and country = 'Ghana';
update schools set admission_info = $q${"ug": "2025/2026: WASSCE credits (A1-C6) in English, Maths, Integrated Science plus 3 relevant electives. Mature: age 25+, 2 years industry experience, written exam. HND holders enter level 300 (BTech top-up). DBS Distinction/Credit enters level 200.", "pg": "First degree not below second class lower. Third class or pass needs 2 years industry experience and a selection interview.", "how_to_apply": "Buy voucher (Finance Office, post offices, banks, or USSD *885#), log in at admissions.stu.edu.gh, complete form, print, post with certificate copies to Registrar, P.O. Box 206, Sunyani.", "deadlines": "No application deadline stated. Mature entrance exam 31 Oct 2025.", "application_fee": "GHS 150 undergraduate; GHS 250 postgraduate or mature; GHS 100 certificate; mature exam GHS 150.", "documents": "Photocopies of certificates or result slips with printed form; birth certificate or JHS certificate for mature applicants.", "sources": ["https://www.stu.edu.gh/images/documents/admissions/STU_Admissions_2025-2026.pdf"]}$q$::jsonb, admission_link = $q$https://www.stu.edu.gh/images/documents/admissions/STU_Admissions_2025-2026.pdf$q$, admission_checked = '2026-11-13' where id = '308071ad-e282-427d-ac85-b85c860dbbf9' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE credits A1-C6 (SSSCE A-D) in six subjects: English, Maths, Integrated Science or Social Studies, plus 3 relevant electives. GCE A Level: 3 passes (one at D or better) plus 5 O Level credits including English and Maths.", "how_to_apply": "All admissions are via the online system (apply.ttuportal.com). Forms bought with cash at TTU Finance, participating banks or regional post offices. Post printed form to Registrar, P.O. Box 256, Takoradi.", "application_fee": "GHS 200 for BTech programmes.", "documents": "Printed copy of online application, photocopies of certificates or result slips, admission number on envelope.", "sources": ["https://ttu.edu.gh/undergraduate-programs/", "https://ttu.edu.gh/how-to-apply/"]}$q$::jsonb, admission_link = $q$https://ttu.edu.gh/undergraduate-programs/$q$, admission_checked = '2026-11-13' where id = 'f300923f-d741-47e6-a688-7f81a1cd8a24' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Degree: C6 or better in 3 core (English, Maths, Integrated Science or Social Studies) and 3 electives, aggregate 36 or better in best six. Mature: age 25+ with O Level or WASSCE passes. HND/Diploma: Second Class Lower for level 200 or 300; Third Class or Pass considered for level 100.", "pg": "MSc/MPhil: good first degree at least Second Class Lower, official transcript, concept paper on research topic, selection interview.", "how_to_apply": "Apply online at https://apply.tatu.edu.gh/", "documents": "Foreign certificates must be verified by GTEC. Official transcript for postgraduate.", "sources": ["https://tatu.edu.gh/admission-entry-requirement/"]}$q$::jsonb, admission_link = $q$https://tatu.edu.gh/admission-entry-requirement/$q$, admission_checked = '2026-11-13' where id = '9b295d90-9bb0-4d81-9a4c-8015cfc8c77b' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Degree: C6 or better in 3 core (English, Maths, Integrated Science or Social Studies) and 3 electives; aggregate of best six not above 36. Diploma: 3 elective credits and at least D7 in English and Maths. HND/Diploma top-up: Second Class Lower for level 200, interview required.", "how_to_apply": "Apply online at admissions.uds.edu.gh (Apply Now).", "sources": ["https://uds.edu.gh/admissions/entry-requirements"]}$q$::jsonb, admission_link = $q$https://uds.edu.gh/admissions/entry-requirements$q$, admission_checked = '2026-11-13' where id = '5bf25143-718c-4c6c-8bea-1c64f32069ea' and country = 'Ghana';
update schools set admission_info = $q${"ug": "2026/2027 regular first degree: six credits, aggregate 36 (WASSCE) or 24 (SSSCE); English, Core Maths, Integrated Science or Social Studies plus 3 relevant electives. A Level: 5 O Level credits plus 3 A Level passes. Diploma/HND placed after certificate assessment.", "english": "International applicants without proof of English proficiency must take an English Proficiency Course before enrolling.", "how_to_apply": "Complete online application (admissions.ucc.edu.gh/how-to-apply). Do not post or hand-deliver hard copies. Programme cannot be changed after submission.", "documents": "Academic certificates for Diploma/HND applicants.", "sources": ["https://ucc.edu.gh/announcements/admission-of-regular-first-degree-students-20262027"]}$q$::jsonb, admission_link = $q$https://ucc.edu.gh/announcements/admission-of-regular-first-degree-students-20262027$q$, admission_checked = '2026-11-13' where id = 'e038bbc8-1b44-4651-a646-4deab0e5ec97' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Page dated 2019/2020 (old): bachelor needs six WASSCE credits A1-C6 including English, Maths, Integrated Science or Social Studies plus 3 electives, aggregate 36 or better. Mature: age 25+, entrance exam. Post-diploma: HND or equivalent.", "how_to_apply": "Buy voucher (GCB, Prudential, Zenith, post offices, UEW cash office), go to uew.edu.gh, Admissions, Apply Online, log in with serial and PIN.", "deadlines": "2019/2020 page only: mature 29 May 2020; direct and post-diploma 4 July 2020. Old, check current.", "application_fee": "2019/2020 page: GHS 200 direct; GHS 300 mature; USD 100 international. Old, check current.", "documents": "Certificates from bodies other than WAEC or accredited Ghana institutions must be assessed by GTEC.", "sources": ["https://uew.edu.gh/node/779", "https://www.uew.edu.gh/node/2508"]}$q$::jsonb, admission_link = $q$https://uew.edu.gh/node/779$q$, admission_checked = '2026-11-13' where id = '7b2b6433-70a8-417a-a00f-0ec3456d379a' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE A1-C6 (SSSCE A-D) in English, Maths, Integrated Science or Social Studies plus 3 relevant electives. Mature: age 25+, 5 years work experience, pass mature entrance exam. HND or UENR diploma with work experience enters level 200 or 300.", "english": "Credit in English Language required; no separate English test stated.", "how_to_apply": "Apply at admissions.uenr.edu.gh. Buy e-voucher (application number and PIN) at Ghana Post (*885#), GCB, Zenith, Prudential, Fidelity, Consolidated Bank, or UENR Finance.", "deadlines": "No deadline stated.", "application_fee": "GHS 230 diploma and undergraduate; GHS 300 postgraduate.", "documents": "Certificates and results; birth certificate for mature; GTEC evaluation report for international applicants.", "sources": ["https://uenr.edu.gh/admission-details/"]}$q$::jsonb, admission_link = $q$https://uenr.edu.gh/admission-details/$q$, admission_checked = '2026-11-13' where id = '41174c6a-91e7-4f2f-a4ce-bae49ba79d16' and country = 'Ghana';
update schools set admission_info = $q${"how_to_apply": "Apply online at apply.ueas.edu.gh. Pioneer cohort 2026/2027 admissions open.", "sources": ["https://ueas.edu.gh/"]}$q$::jsonb, admission_link = $q$https://ueas.edu.gh/$q$, admission_checked = '2026-11-13' where id = '6e6f83bf-5304-4939-8a84-0ad5802fc1b4' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE credits A1-C6 in core English, Core Maths, Integrated Science or Social Studies plus 3 electives; aggregate 36 or better (SSSCE 24). A Level: 3 passes plus 5 O Level credits. HND Second Class: year 3 entry after interview. Mature: age 25+, written exam and interview.", "english": "Foreign applicants from non-English-speaking countries must show English proficiency; GTEC assesses qualifications.", "how_to_apply": "Online admissions portal linked from the university site; steps not stated.", "sources": ["https://www.uesd.edu.gh/b-sc-sustainable-development/"]}$q$::jsonb, admission_link = $q$https://www.uesd.edu.gh/b-sc-sustainable-development/$q$, admission_checked = '2026-11-13' where id = 'b411b853-2be1-4e86-afc0-5669d3b9e3f0' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE credits A1-C6 (SSSCE A-D) in English, Core Maths, Integrated Science, Social Studies plus 3 electives. Aggregate 24 for regular and 30 for distance admissions. A and O Levels: 3 A Level subjects plus 5 O Level passes including English and Maths. IB: usually grade 4 or higher.", "how_to_apply": "Online application via admissions.ug.edu.gh; steps on a separate How to Apply page.", "sources": ["https://admissions.ug.edu.gh/undergraduate/entry-requirements"]}$q$::jsonb, admission_link = $q$https://admissions.ug.edu.gh/undergraduate/entry-requirements$q$, admission_checked = '2026-11-13' where id = '4722eaaa-ec08-41e4-a145-70eea4f5db48' and country = 'Ghana';
update schools set admission_info = $q${"ug": "2026/2027: WASSCE/SSSCE credits in English, Core Maths, Integrated Science and Social Studies plus 3 relevant electives. Social Studies at least C6/D, not in aggregate. Awaiting-result applicants not eligible. A Level: 5 O Level passes plus A Level Chemistry, Physics, Biology.", "english": "Foreign certificates must be authenticated by GTEC and translated into English.", "how_to_apply": "Admissions portal at admissions.uhas.edu.gh; steps on Application Guidelines page.", "documents": "GTEC authentication and English translation for foreign certificates.", "sources": ["https://uhas.edu.gh/uhas/admission/undergraduate-entry-requirements/entry-requirements"]}$q$::jsonb, admission_link = $q$https://uhas.edu.gh/uhas/admission/undergraduate-entry-requirements/entry-requirements$q$, admission_checked = '2026-11-13' where id = 'f8ad2dd8-4d96-4a83-a1fb-d511b22d0c35' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Credits in English, Maths, Integrated Science (some programmes accept Social Studies) plus usually 3 electives such as Physics, Maths, Chemistry. Mature: age 25+, credits in 5 subjects including English, Maths and a Science, relevant experience, written exam or interview. Top-up for Diploma or HND.", "documents": "Mature applicants: birth certificate at least 5 years old.", "sources": ["https://umat.edu.gh/entry-requirement-bsc-programmes"]}$q$::jsonb, admission_link = $q$https://umat.edu.gh/entry-requirement-bsc-programmes$q$, admission_checked = '2026-11-13' where id = 'cc0ca998-704f-4364-aa32-9f25f08625e8' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Level 100: credits in English, Maths, Integrated Science or Social Studies plus 3 electives. Level 200: HND Second Class Lower, ABCE, A Level or professional qualification. Level 300: HND Second Upper, diploma FCGPA 2.5+. Mature: age 25+, 5 years work, E in six SSSCE subjects, pass access exams (40% each) and interview.", "english": "International applicants from non-English-speaking countries need evidence of English proficiency.", "how_to_apply": "Online portal at upsasip.com/admissions (Apply Now).", "deadlines": "Mature applicants 2026: access course fees by 5 June, registration closes 5 July, exams 7-8 Aug 2026.", "application_fee": "Mature access exams: Maths GHS 250, English GHS 250, Aptitude GHS 300. General fee not stated.", "documents": "Mature: birth certificate and proof of employment. International: GTEC assessment, English proficiency evidence, Non-Citizen Ghana Card.", "sources": ["https://admissions.upsa.edu.gh/admissions/undergrad-entry-requirements/"]}$q$::jsonb, admission_link = $q$https://admissions.upsa.edu.gh/admissions/undergrad-entry-requirements/$q$, admission_checked = '2026-11-13' where id = '7d6ca635-5282-4387-a978-ba3076a63a88' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE/SSSCE credits in six subjects: English, Maths and other core plus 3 relevant electives. A Level: 3 passes plus 5 O Level credits. Mature: age 25+ and pass Mature Entrance Exam. Foreign: baccalaureate or diploma with GTEC evaluation. Page label: Admissions 2025.", "pg": "Master's: relevant bachelor's degree, Second Class Lower or better, and admission interview. PhD: relevant master's and interview.", "english": "No English test stated; only English as a subject.", "how_to_apply": "Online application portal linked from vvu.edu.gh/admissions (admissions.vvu.edu.gh).", "sources": ["https://vvu.edu.gh/entry-requirement"]}$q$::jsonb, admission_link = $q$https://vvu.edu.gh/entry-requirement$q$, admission_checked = '2026-11-13' where id = '25ad114e-7259-4341-8f33-afb66f1fbd1a' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE/SSSCE credits in six subjects: English, Maths and other core plus 3 relevant electives. A Level: 3 passes plus 5 O Level credits. Mature: age 25+ and pass Mature Entrance Exam. Foreign: baccalaureate or diploma with GTEC evaluation. Page label: Admissions 2025.", "pg": "Master's: relevant bachelor's degree, Second Class Lower or better, and admission interview. PhD: relevant master's and interview.", "english": "No English test stated; only English as a subject.", "how_to_apply": "Online application portal linked from vvu.edu.gh/admissions (admissions.vvu.edu.gh).", "sources": ["https://vvu.edu.gh/entry-requirement"]}$q$::jsonb, admission_link = $q$https://vvu.edu.gh/entry-requirement$q$, admission_checked = '2026-11-13' where id = 'a431a251-e90e-4c74-9eee-f1e5d19683ba' and country = 'Ghana';
update schools set admission_info = $q${"ug": "WASSCE/SSSCE credits in six subjects: English, Maths and other core plus 3 relevant electives. A Level: 3 passes plus 5 O Level credits. Mature: age 25+ and pass Mature Entrance Exam. Foreign: baccalaureate or diploma with GTEC evaluation. Page label: Admissions 2025.", "pg": "Master's: relevant bachelor's degree, Second Class Lower or better, and admission interview. PhD: relevant master's and interview.", "english": "No English test stated; only English as a subject.", "how_to_apply": "Online application portal linked from vvu.edu.gh/admissions (admissions.vvu.edu.gh).", "sources": ["https://vvu.edu.gh/entry-requirement"]}$q$::jsonb, admission_link = $q$https://vvu.edu.gh/entry-requirement$q$, admission_checked = '2026-11-13' where id = '701cd364-f5d4-497f-9a40-e9fa05f496a3' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Requirements vary by programme. Mature: age 25+, six-week course, entrance exam, possible interview (not for Nursing or Law). Nursing needs a six-week access course. Professional body members (ICAG, ACCA, CIMA and others) may be considered.", "english": "Foreign applicants need WASSCE/SSSCE equivalent and fluent English for Nursing; result slips translated into English.", "how_to_apply": "Apply through the university website. Foreign and francophone applicants first buy an Online Serial Number by MoMo, card or Flutterwave, then register on the admission portal.", "documents": "Transfer: university transcripts and result slips. Foreign: English-translated results. Professional: proof of membership.", "sources": ["https://wiuc-ghana.edu.gh/faqs/"]}$q$::jsonb, admission_link = $q$https://wiuc-ghana.edu.gh/faqs/$q$, admission_checked = '2026-11-13' where id = '98cd71d6-00f9-4c6e-ae5a-6eface53847a' and country = 'Ghana';
update schools set admission_info = $q${"ug": "Requirements vary by programme. Mature: age 25+, six-week course, entrance exam, possible interview (not for Nursing or Law). Nursing needs a six-week access course. Professional body members (ICAG, ACCA, CIMA and others) may be considered.", "english": "Foreign applicants need WASSCE/SSSCE equivalent and fluent English for Nursing; result slips translated into English.", "how_to_apply": "Apply through the university website. Foreign and francophone applicants first buy an Online Serial Number by MoMo, card or Flutterwave, then register on the admission portal.", "documents": "Transfer: university transcripts and result slips. Foreign: English-translated results. Professional: proof of membership.", "sources": ["https://wiuc-ghana.edu.gh/faqs/"]}$q$::jsonb, admission_link = $q$https://wiuc-ghana.edu.gh/faqs/$q$, admission_checked = '2026-11-13' where id = '4474153e-ff8c-4da6-a031-2973868fc810' and country = 'Ghana';
